def maxMinSweetness(sweetness, k):
    def ok(x):
        pieces = cur = 0
        for s in sweetness:
            cur += s
            if cur >= x:
                pieces += 1
                cur = 0
        return pieces >= k + 1

    lo, hi = 1, sum(sweetness) // (k + 1)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
